{
  "$schema": "https://ui.shadcn.com/schema/registry-item.json",
  "name": "floating-action-bar",
  "type": "registry:ui",
  "registryDependencies": [
    "@cipher/button",
    "@cipher/cipher-base",
    "@cipher/dropdown-menu",
    "@cipher/icon",
    "@cipher/top-bar"
  ],
  "dependencies": [
    "motion@^13.2.0"
  ],
  "files": [
    {
      "path": "src/components/cipher/ui/floating-action-bar.tsx",
      "type": "registry:file",
      "target": "src/components/cipher/ui/floating-action-bar.tsx",
      "content": "import * as React from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { exit, snap, spring } from "../lib/motion";
import { cn } from "../lib/utils";
import { useCollisionBoundary, usePortalContainer, useToastLayer } from "../scope";
import { Button } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from "./dropdown-menu";
import { type IconSource } from "./icon";
import { useActionBarReserve } from "./top-bar";

import styles from "./floating-action-bar.module.css";

export interface FloatingAction {
  label: string;
  icon?: IconSource;
  onClick: () => void;
  danger?: boolean;
  disabled?: boolean;
  /** Blocks the action and says why, as Button disabledReason: it stays focusable, the reason shows in a tooltip on hover and keyboard focus and is its accessible description. In More it is the item's description. */
  disabledReason?: string;
  loading?: boolean;
}

export type FloatingActionBarProps = {
  count: number;
  total?: number;
  onSelectAll?: () => void;
  actions?: readonly FloatingAction[];
  moreActions?: readonly FloatingAction[];
  onClear: () => void;
  noun?: string;
  label?: string;
  className?: string;
};

const roving = (event: React.KeyboardEvent<HTMLDivElement>, onClear: () => void) => {
  if (!event.currentTarget.contains(event.target as Node) || event.defaultPrevented) return;
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    onClear();
    return;
  }
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  const buttons = [...event.currentTarget.querySelectorAll<HTMLElement>("button:not(:disabled)")];
  const index = buttons.indexOf(document.activeElement as HTMLElement);
  if (index === -1) return;
  event.preventDefault();
  const next =
    event.key === "Home"
      ? 0
      : event.key === "End"
        ? buttons.length - 1
        : (index + (event.key === "ArrowRight" ? 1 : -1) + buttons.length) % buttons.length;
  buttons[next]?.focus();
};

export const FloatingActionBar = ({
  count,
  total,
  onSelectAll,
  actions = [],
  moreActions = [],
  onClear,
  noun = "selected",
  label = "Bulk actions",
  className
}: FloatingActionBarProps) => {
  const reduced = useReducedMotion();
  const [lastCount, setLastCount] = React.useState(count);
  const returnFocus = React.useRef<HTMLElement | null>(null);
  const bar = React.useRef<HTMLDivElement | null>(null);
  if (count > 0 && count !== lastCount) setLastCount(count);
  const shown = count > 0;
  const [clearOfToasts, setClearOfToasts] = React.useState(false);
  useActionBarReserve(shown, shown && !clearOfToasts);
  const portal = usePortalContainer();
  const boundary = useCollisionBoundary();
  const toastLayer = useToastLayer();
  React.useEffect(() => {
    if (shown || !bar.current?.contains(document.activeElement)) return;
    returnFocus.current?.focus();
  }, [shown]);
  const visibleCount = shown ? count : lastCount;
  const actionsRef = React.useRef<HTMLSpanElement | null>(null);
  const widths = React.useRef(new Map<string, number>());
  const [fit, setFit] = React.useState(actions.length);
  const measure = React.useCallback(() => {
    const node = bar.current;
    const group = actionsRef.current;
    if (!node || !group) return;
    const style = getComputedStyle(node);
    const viewport = document.documentElement.clientWidth;
    const inset = parseFloat(style.getPropertyValue("--cipher-space-16"));
    const toast = parseFloat(style.getPropertyValue("--cipher-size-toast"));
    const toastLeft = viewport - inset - Math.min(toast, viewport - 2 * inset);
    const besideToasts = node.getBoundingClientRect().right + inset <= toastLeft;
    const positions = toastLayer?.getAttribute("data-toast-position")?.split(" ") ?? [];
    const clear =
      positions.length > 0 &&
      positions.every(
        (position) => position.startsWith("top") || (position === "bottom-right" && besideToasts)
      );
    setClearOfToasts((current) => (current === clear ? current : clear));
    group.querySelectorAll<HTMLElement>("[data-action-label]").forEach((button) => {
      widths.current.set(button.dataset.actionLabel ?? "", button.offsetWidth);
    });
    const more = group.querySelector<HTMLElement>("[data-action-more]");
    if (more) widths.current.set("�more", more.offsetWidth);
    const container = boundary?.clientWidth ?? document.documentElement.clientWidth;
    const gap = parseFloat(getComputedStyle(group).columnGap) || 0;
    const limit = Math.min(container - 32, parseFloat(style.maxWidth) || Infinity);
    const available = limit - (node.offsetWidth - group.offsetWidth);
    const known = actions.every((action) => widths.current.has(action.label));
    if (!known) return;
    const moreWidth = widths.current.get("�more") ?? 72;
    let next = actions.length;
    const total = (k: number) =>
      actions
        .slice(0, k)
        .reduce((sum, action) => sum + (widths.current.get(action.label) ?? 0), 0) +
      Math.max(0, k - 1 + (k < actions.length || moreActions.length ? 1 : 0)) * gap +
      (k < actions.length || moreActions.length ? moreWidth : 0);
    while (next > 0 && total(next) > available + 0.5) next -= 1;
    setFit((current) => (current === next ? current : next));
  }, [actions, moreActions.length, boundary, toastLayer]);
  const labels = actions.map((action) => action.label).join("�");
  React.useLayoutEffect(() => {
    setFit(labels ? labels.split("�").length : 0);
  }, [labels]);
  React.useLayoutEffect(() => {
    if (!shown) return undefined;
    measure();
    const observer = new ResizeObserver(measure);
    if (boundary) observer.observe(boundary);
    if (bar.current) observer.observe(bar.current);
    window.addEventListener("resize", measure);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", measure);
    };
  });
  const inline = actions.slice(0, fit);
  const overflow = [...actions.slice(fit), ...moreActions];
  const floating = (
    <AnimatePresence>
      {shown && (
        <motion.div
          ref={bar}
          key="bar"
          data-slot="floating-action-bar"
          role="toolbar"
          data-cipher-escape-owner=""
          aria-label={label}
          className={cn(styles.bar, className)}
          initial={{ opacity: 0, y: reduced ? 0 : 16 }}
          animate={{ opacity: 1, y: 0, transition: reduced ? snap : spring.moderate }}
          exit={{ opacity: 0, y: reduced ? 0 : 16, transition: reduced ? snap : exit.moderate }}
          onFocus={(event: React.FocusEvent<HTMLDivElement>) => {
            const from = event.relatedTarget as HTMLElement | null;
            if (from && !event.currentTarget.contains(from)) returnFocus.current = from;
          }}
          onKeyDown={(event: React.KeyboardEvent<HTMLDivElement>) => roving(event, onClear)}
        >
          <span className={styles.count} role="status">
            <span className={styles.number}>{visibleCount}</span>
            <span className={styles.noun}>{noun}</span>
          </span>
          {total !== undefined && onSelectAll && visibleCount < total && (
            <Button variant="link" size="sm" className={styles.selectAll} onClick={onSelectAll}>
              Select all {total}
            </Button>
          )}
          <span className={styles.rule} aria-hidden="true" />
          <span className={styles.actions} ref={actionsRef}>
            {inline.map((action) => (
              <Button
                key={action.label}
                data-action-label={action.label}
                variant={action.danger ? "danger-ghost" : "ghost"}
                size="sm"
                icon={action.icon}
                disabled={action.disabled}
                disabledReason={action.disabledReason}
                loading={action.loading}
                onClick={action.onClick}
              >
                {action.label}
              </Button>
            ))}
            {overflow.length > 0 && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="sm" layout="trigger" data-action-more="">
                    More
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent side="top" align="end">
                  {overflow.map((action) => (
                    <DropdownMenuItem
                      key={action.label}
                      variant={action.danger ? "destructive" : "default"}
                      disabled={action.disabled || Boolean(action.disabledReason) || action.loading}
                      description={action.disabledReason}
                      onSelect={action.onClick}
                    >
                      {action.loading ? `${action.label} (running)` : action.label}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </span>
          <Button variant="ghost" size="sm" onClick={onClear}>
            Clear
          </Button>
        </motion.div>
      )}
    </AnimatePresence>
  );
  return (
    <>
      {shown && <span data-slot="floating-action-bar-reserve" className={styles.reserve} hidden />}
      {portal ? createPortal(floating, portal) : floating}
    </>
  );
};
"
    },
    {
      "path": "src/components/cipher/ui/floating-action-bar.module.css",
      "type": "registry:file",
      "target": "src/components/cipher/ui/floating-action-bar.module.css",
      "content": ".bar {
  position: fixed;
  bottom: var(--cipher-space-action-bar-offset);
  left: 50%;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  max-width: calc(100% - 2 * var(--cipher-space-16));
  height: var(--cipher-size-action-bar);
  margin-inline: auto;
  padding: 0 var(--cipher-space-8) 0 var(--cipher-space-16);
  translate: -50% 0;
  border: 1px solid var(--cipher-toast-line);
  border-radius: 0;
  background: var(--cipher-toast-bg);
  color: var(--cipher-toast-text);
  box-shadow: var(--cipher-shadow-pop);
  white-space: nowrap;
}
:global([data-slot="app-inset"])[data-action-bar-reserve] {
  padding-bottom: calc(var(--cipher-size-action-bar) + var(--cipher-space-action-bar-offset));
}
.count {
  display: inline-flex;
  align-items: baseline;
  gap: var(--cipher-space-4);
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-type-label-font-size);
  line-height: var(--cipher-type-label-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-label-letter-spacing);
}
.number {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.noun {
  color: var(--cipher-toast-muted);
}
.selectAll.selectAll {
  color: var(--cipher-toast-text);
}
.rule {
  flex: none;
  width: 1px;
  height: var(--cipher-space-20);
  background: var(--cipher-toast-line);
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-4);
  min-width: 0;
  overflow: hidden;
}
@media (max-width: 400px) {
  .selectAll {
    display: none;
  }
  .noun {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }
}
"
    }
  ]
}

