export type GridValue = string | null;
export type ParseResult = { value: GridValue } | { error: string };
export interface GridCell {
  rowId: string;
  columnId: string;
}
export interface GridSelection {
  active: GridCell;
  anchor: GridCell;
}
export interface GridChange<Row> extends GridCell {
  row: Row;
  previous: GridValue;
  value: GridValue;
}
export interface GridColumn<Row> {
  id: string;
  header: string;
  type?: string;
  getValue: (row: Row) => GridValue;
  parse?: (text: GridValue, row: Row) => ParseResult;
  format?: (value: GridValue, row: Row) => string;
  editable?: boolean;
  nullable?: boolean;
  primaryKey?: boolean;
  sensitive?: boolean;
  width?: number;
  minWidth?: number;
  maxWidth?: number;
  align?: "start" | "end";
}

export function encodeTsv(rows: readonly (readonly GridValue[])[]): string {
  return rows
    .map((row) =>
      row
        .map((value) => {
          if (value === null) return "\\N";
          if (value === "" || value === "\\N" || /[\t\n\r"]/.test(value))
            return `"${value.replaceAll('"', '""')}"`;
          return value;
        })
        .join("\t")
    )
    .join("\n");
}

export function decodeTsv(text: string): { rows: GridValue[][] } | { error: string } {
  const rows: GridValue[][] = [];
  let row: GridValue[] = [];
  let value = "";
  let quoted = false;
  let wasQuoted = false;
  let afterQuote = false;
  const pushCell = () => {
    row.push(!wasQuoted && value === "\\N" ? null : value);
    value = "";
    wasQuoted = false;
    afterQuote = false;
  };
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    if (quoted) {
      if (char === '"' && text[i + 1] === '"') {
        value += '"';
        i += 1;
      } else if (char === '"') {
        quoted = false;
        afterQuote = true;
      } else value += char;
    } else if (char === "\t") pushCell();
    else if (char === "\n" || char === "\r") {
      if (char === "\r" && text[i + 1] === "\n") i += 1;
      pushCell();
      rows.push(row);
      row = [];
    } else if (char === '"' && value === "" && !afterQuote) {
      quoted = true;
      wasQuoted = true;
    } else if (afterQuote) return { error: "A quoted cell must end before the next separator." };
    else value += char;
  }
  if (quoted) return { error: "A quoted cell is missing its closing quote." };
  pushCell();
  rows.push(row);
  return { rows };
}

const signedIntegerBits: Readonly<Partial<Record<string, number>>> = {
  int2: 16,
  smallint: 16,
  int4: 32,
  integer: 32,
  int8: 64,
  bigint: 64
};

export function parseGridValue<Row>(
  column: GridColumn<Row>,
  value: GridValue,
  row: Row
): ParseResult {
  if (column.parse) return column.parse(value, row);
  if (value === null)
    return column.nullable ? { value: null } : { error: `${column.header} cannot be NULL.` };
  const type = column.type?.toLowerCase() ?? "text";
  const bits = signedIntegerBits[type];
  if (bits !== undefined) {
    if (!/^-?\d+$/.test(value)) return { error: `${column.header} needs a whole number.` };
    const magnitude = 2n ** BigInt(bits - 1);
    const exact = BigInt(value);
    if (exact < -magnitude || exact >= magnitude)
      return { error: `${column.header} must be between ${-magnitude} and ${magnitude - 1n}.` };
  }
  if (
    /^(numeric|decimal|float4|float8|real)$/.test(type) &&
    !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(value)
  )
    return { error: `${column.header} needs a number.` };
  if (/^(bool|boolean)$/.test(type) && !/^(true|false)$/.test(value))
    return { error: `${column.header} needs true or false.` };
  if (type === "uuid" && !/^[\da-f]{8}(?:-[\da-f]{4}){3}-[\da-f]{12}$/i.test(value))
    return { error: `${column.header} needs a UUID.` };
  if (/^jsonb?$/.test(type)) {
    try {
      JSON.parse(value);
    } catch {
      return { error: `${column.header} needs valid JSON.` };
    }
  }
  return { value };
}

export function canEditColumn<Row>(column: GridColumn<Row>): boolean {
  return !column.sensitive && (column.editable ?? !column.primaryKey);
}

export function pasteGrid<Row>({
  rows,
  columns,
  getRowId,
  active,
  text
}: {
  rows: readonly Row[];
  columns: readonly GridColumn<Row>[];
  getRowId: (row: Row) => string;
  active: GridCell;
  text: string;
}): { changes: GridChange<Row>[] } | { error: string } {
  const parsed = decodeTsv(text);
  if ("error" in parsed) return parsed;
  const firstRow = rows.findIndex((row) => getRowId(row) === active.rowId);
  const firstColumn = columns.findIndex((column) => column.id === active.columnId);
  if (firstRow < 0 || firstColumn < 0)
    return { error: "The selected cell is no longer available." };
  const changes: GridChange<Row>[] = [];
  for (let r = 0; r < parsed.rows.length; r += 1) {
    const line = parsed.rows[r];
    if (!line) return { error: "The pasted row is missing." };
    const row = rows[firstRow + r];
    if (!row || firstColumn + line.length > columns.length)
      return { error: "The pasted cells do not fit in the available rows and columns." };
    for (let c = 0; c < line.length; c += 1) {
      const value = line[c];
      if (value === undefined) return { error: "The pasted cell is missing." };
      const column = columns[firstColumn + c];
      if (!column || !canEditColumn(column))
        return { error: "The pasted range includes a read-only or protected cell." };
      const result = parseGridValue(column, value, row);
      if ("error" in result) return { error: `Row ${firstRow + r + 1}: ${result.error}` };
      const previous = column.getValue(row);
      if (previous !== result.value)
        changes.push({
          rowId: getRowId(row),
          columnId: column.id,
          row,
          previous,
          value: result.value
        });
    }
  }
  return { changes };
}

export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [key: string]: JsonValue };
export type Redaction = readonly string[] | ((key: string) => boolean);
export type JsonNode = { start: number; end: number } & (
  | { kind: "scalar"; raw: string }
  | { kind: "array"; items: JsonNode[] }
  | { kind: "object"; entries: { key: string; node: JsonNode }[] }
);
const REDACTED = JSON.stringify("<redacted>");
export function redactJson(value: JsonValue, redact?: Redaction): JsonValue {
  const keys = Array.isArray(redact) ? new Set(redact.map((key) => key.toLowerCase())) : null;
  const match = (key: string) =>
    typeof redact === "function" ? redact(key) : (keys?.has(key.toLowerCase()) ?? false);
  const visit = (node: JsonValue): JsonValue =>
    Array.isArray(node)
      ? node.map(visit)
      : node !== null && typeof node === "object"
        ? Object.fromEntries(
            Object.entries(node).map(([key, child]) => [
              key,
              match(key) ? "<redacted>" : visit(child)
            ])
          )
        : node;
  return visit(value);
}
function parseDocument(source: string): JsonNode {
  let cursor = 0;
  let nodes = 0;
  const whitespace = () => {
    while (/[ \t\r\n]/.test(source[cursor] ?? "") && cursor < source.length) cursor += 1;
  };
  const string = () => {
    const start = cursor;
    cursor += 1;
    while (cursor < source.length) {
      const char = source[cursor];
      cursor += 1;
      if (char === "\\") cursor += 1;
      else if (char === '"') return JSON.parse(source.slice(start, cursor)) as string;
    }
    throw new Error("Unterminated string");
  };
  const parse = (depth: number): JsonNode => {
    nodes += 1;
    if (depth > 128 || nodes > 50000) throw new RangeError("JSON exceeds inspection limits");
    whitespace();
    const start = cursor;
    if (source[cursor] === "{") {
      cursor += 1;
      whitespace();
      const entries: { key: string; node: JsonNode }[] = [];
      if (source[cursor] !== "}")
        while (cursor < source.length) {
          whitespace();
          if (source[cursor] !== '"') throw new Error("Expected key");
          const key = string();
          whitespace();
          if (source[cursor] !== ":") throw new Error("Expected colon");
          cursor += 1;
          entries.push({ key, node: parse(depth + 1) });
          whitespace();
          if (source[cursor] !== ",") break;
          cursor += 1;
        }
      if (source[cursor] !== "}") throw new Error("Expected object end");
      cursor += 1;
      return { kind: "object", entries, start, end: cursor };
    }
    if (source[cursor] === "[") {
      cursor += 1;
      whitespace();
      const items: JsonNode[] = [];
      if (source[cursor] !== "]")
        while (cursor < source.length) {
          items.push(parse(depth + 1));
          whitespace();
          if (source[cursor] !== ",") break;
          cursor += 1;
        }
      if (source[cursor] !== "]") throw new Error("Expected array end");
      cursor += 1;
      return { kind: "array", items, start, end: cursor };
    }
    if (source[cursor] === '"') string();
    else {
      const token = [REDACTED]]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)/.exec(
        source.slice(cursor)
      );
      if (!token) throw new Error("Expected JSON value");
      cursor += token[0].length;
    }
    return { kind: "scalar", raw: source.slice(start, cursor), start, end: cursor };
  };
  const node = parse(0);
  whitespace();
  if (cursor !== source.length) throw new Error("Unexpected trailing text");
